import { useRecoilState } from "recoil";
import { queueState, logState } from "./recoilState";
import { cloneWithMethods } from "../util/cloneWithMethods";

export function useQueue() {
  const [queue, setQueue] = useRecoilState(queueState);
  const [log, setLog] = useRecoilState(logState);

  // item = {battle, text, allowAct=true, autoActTurn=true, noLog=true, onlyLog=true, bottomMode, waitInput}
  // bottomMode: 화면 하단 UI(bottom)의 모드를 지정 ("skill" | "mustSwitch" | "switchBySkill" | "auto")
  // waitInput: 유저의 입력(기술/교체 선택 등)을 기다리기 위해 큐 진행을 멈춰야 하는 아이템인지 여부 (true/false)

  // allowAct: 행동 (기술버튼, 교체버튼) 잠금 해제
  // 밑의 queueCheck에서 사용
  // 턴 종료시 "무엇을 할까?" (turnEnd.js),
  // 유턴 사용시 "누구로 교체할까?" (skillEffect.js),
  // 스킬 사용 불가 메세지 (pp소진, 구애 고정, 도발) (Skillbutton.js)

  // autoActTurn: 이전 턴의 행동(역린, 메테오빔, 파괴광선)으로 인해 행동이 자동으로 결정되는 경우
  // battleScreen.js에서 사용
  // turnEnd.js에서 auto, charge, recharge중 하나라도 on이면 턴 종료시 삽입함

  // noLog: 화면엔 나오지만 로그 기록 모달에 남지 않음
  // 밑의 dequeue에서 noLog면 넣지 않음
  // 스킬 사용 불가 메세지 (pp소진, 구애 고정, 도발) (Skillbutton.js)를 로그 목록에 넣지 않음.
  // 무엇을 할까? 누구로 교체할까?는 그냥 텍스트로 조건문 처리

  // onlyLog : 반대로 화면엔 안나오지만 로그 목록에 넣음 (N번쨰 턴)
  // battleScreen에서 onlyLog면 바로 dequeue함
  // battleStart에서 시작할때마다 넣음

  const enqueue = (item) => {
    if (item && !item.id) {
      item.id = typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 11);
    }
    const deepCopiedItem = cloneWithMethods(item); // 메서드까지 깊은 복사하는 함수
    setQueue((prevQueue) => [...prevQueue, deepCopiedItem]);
  };

  const dequeue = () => {
    let removedItem = null;

    setQueue((prevQueue) => {
      if (prevQueue.length === 0) return prevQueue;

      removedItem = prevQueue[0];
      return prevQueue.slice(1);
    });

    if (removedItem) {
      if (!(removedItem.text && (removedItem.text.includes("무엇을 할까?") || removedItem.text.includes("누구로 교체")))) {
        if (!removedItem.noLog) {
          // logText가 있으면 로그에는 logText로 기록 (화면 표시 텍스트와 다르게)
          const logItem = removedItem.logText ? { ...removedItem, text: removedItem.logText } : removedItem;
          setLog((prevLog) => [...prevLog, logItem]);
        }
      }
    }

    return removedItem;
  };

  const updateHead = (updater, curBattle, extraAfterHead = [], options = {}) => {
    setQueue((prevQueue) => {
      if (prevQueue.length === 0) return prevQueue;
      const head = typeof updater === "function" ? updater(prevQueue[0]) : updater;
      const deepCopiedHead = cloneWithMethods(head);
      const deepCopiedExtras = (extraAfterHead || []).map((item) => {
        const nextItem = { ...item };
        if (!nextItem.id) {
          nextItem.id =
            typeof crypto !== "undefined" && crypto.randomUUID
              ? crypto.randomUUID()
              : Math.random().toString(36).substring(2, 11);
        }
        return cloneWithMethods(nextItem);
      });

      if (options?.dropRemaining) {
        return [deepCopiedHead, ...deepCopiedExtras];
      }

      if (!curBattle) {
        return [deepCopiedHead, ...deepCopiedExtras, ...prevQueue.slice(1)];
      }

      const rest = prevQueue.slice(1).map((item) => {
        if (!item.battle) return item;
        const nextItemBattle = cloneWithMethods(item.battle);
        if ("hasKnockoutAugmentThisRound" in curBattle) {
          nextItemBattle.hasKnockoutAugmentThisRound = curBattle.hasKnockoutAugmentThisRound;
        }
        const sourcePlayerTeam = [curBattle.player, curBattle.playerBench1, curBattle.playerBench2];
        const targetPlayerTeam = [nextItemBattle.player, nextItemBattle.playerBench1, nextItemBattle.playerBench2];
        sourcePlayerTeam.forEach((sPoke, pIdx) => {
          if (sPoke && targetPlayerTeam[pIdx]) {
            const clonedPoke = cloneWithMethods(sPoke);
            if (pIdx === 0) nextItemBattle.player = clonedPoke;
            else if (pIdx === 1) nextItemBattle.playerBench1 = clonedPoke;
            else if (pIdx === 2) nextItemBattle.playerBench2 = clonedPoke;
          }
        });
        const sourceNpcTeam = [curBattle.npc, curBattle.npcBench1, curBattle.npcBench2];
        const targetNpcTeam = [nextItemBattle.npc, nextItemBattle.npcBench1, nextItemBattle.npcBench2];
        sourceNpcTeam.forEach((sPoke, pIdx) => {
          if (sPoke && targetNpcTeam[pIdx]) {
            const clonedPoke = cloneWithMethods(sPoke);
            if (pIdx === 0) nextItemBattle.npc = clonedPoke;
            else if (pIdx === 1) nextItemBattle.npcBench1 = clonedPoke;
            else if (pIdx === 2) nextItemBattle.npcBench2 = clonedPoke;
          }
        });
        const updatedText =
          typeof item.text === "string" &&
          item.text.includes("무엇을 할까?") &&
          nextItemBattle.player
            ? nextItemBattle.player.names("는") + " 무엇을 할까?"
            : item.text;
        return {
          ...item,
          text: updatedText,
          battle: nextItemBattle,
        };
      });

      return [deepCopiedHead, ...deepCopiedExtras, ...rest];
    });
  };

  const insertAfterHead = (items = []) => {
    setQueue((prevQueue) => {
      if (prevQueue.length === 0) return items.map(cloneWithMethods);
      const deepCopiedItems = items.map((item) => {
        const nextItem = { ...item };
        if (!nextItem.id) {
          nextItem.id =
            typeof crypto !== "undefined" && crypto.randomUUID
              ? crypto.randomUUID()
              : Math.random().toString(36).substring(2, 11);
        }
        return cloneWithMethods(nextItem);
      });
      return [prevQueue[0], ...deepCopiedItems, ...prevQueue.slice(1)];
    });
  };

  const resetQueue = () => {
    setQueue((prev) => (prev.length > 0 ? [] : prev));
  };

  const initQueue = () => {
    setQueue((prev) => (prev.length > 0 ? [] : prev));
    setLog([]);
  };

  const queueCheck = () => {
    if (queue.length > 0) {
      if (queue[0].allowAct) return true;
      //turnEnd.js에서 마지막에 넣은 "~는 무엇을 할까?"는 allowAct 가능하게
      return false;
    }
    return true;
  };

  return {
    queueObject: {
      queue,
      log,
      enqueue,
      dequeue,
      updateHead,
      insertAfterHead,
      resetQueue,
      initQueue,
      queueCheck,
    },
  };
}
