import React, { useState } from "react";
import styled, { keyframes } from "styled-components";
import { AugmentIcon } from "./AugmentIcon";
import { AUGMENT_POKEMON_PREVIEW_MAP, getAugmentGrantInfo } from "./augmentPreviewConstants";
import AugmentGrantPreviewModal from "./AugmentGrantPreviewModal";
import AugmentPokemonPreviewModal from "./AugmentPokemonPreviewModal";
import AugmentSynergyPreviewModal from "./AugmentSynergyPreviewModal";
import sampleList from "../../../entity/Pokemon/pokemonSampleList";
import { getAugmentText, isBuffAugment, isCurseAugment, isSynergyAugment, isNormalAugment, getAugmentSynergyInfo, hasAnvilStats, getAnvilStatsStatusDesc } from "../../../entity/Augment/AugmentData";

const AugmentStatusModal = ({ battle, team = [], initialPokemon = null, onClose }) => {
  const [previewInfo, setPreviewInfo] = useState(null);
  const [synergyPreviewInfo, setSynergyPreviewInfo] = useState(null);
  const [grantPreviewInfo, setGrantPreviewInfo] = useState(null);
  const [selectedAugId, setSelectedAugId] = useState(null);

  const handleCardClick = (e, aug) => {
    e.stopPropagation();
    setSelectedAugId((prev) => (prev === aug.id ? null : aug.id));
  };
  const resolvedTeam = team && team.length > 0 ? team : [battle?.player, battle?.playerBench1, battle?.playerBench2].filter(Boolean);

  const [activePokemon, setActivePokemon] = useState(() => {
    if (initialPokemon) {
      const found = resolvedTeam.find((p) => p === initialPokemon || p?.id === initialPokemon?.id || p?.originalIndex === initialPokemon?.originalIndex);
      if (found) return found;
    }
    return resolvedTeam[0] || null;
  });

  if (!resolvedTeam || resolvedTeam.length === 0) return null;

  const currentAugments = [...(activePokemon?.augments || [])];
  if (
    hasAnvilStats(activePokemon) &&
    !currentAugments.some((a) => (typeof a === "string" ? a === "anvilStat" : a?.id === "anvilStat"))
  ) {
    currentAugments.push({
      id: "anvilStat",
      name: "모루 능력치",
      desc: getAnvilStatsStatusDesc(activePokemon),
      buf: true,
      cost: "-",
    });
  }
  const sortedAugments = [...currentAugments].sort((a, b) => {
    // 0: 일반 증강, 1: 시너지, 2: 버프, 3: 디버프
    const getOrder = (aug) => {
      if (isCurseAugment(aug)) return 3;
      if (isBuffAugment(aug)) return 2;
      if (isSynergyAugment(aug)) return 1;
      return 0;
    };
    const orderA = getOrder(a);
    const orderB = getOrder(b);
    if (orderA !== orderB) return orderA - orderB;
    return (a.name || "").localeCompare(b.name || "");
  });

  return (
    <ModalOverlay onClick={onClose}>
      <ModalContainer onClick={(e) => e.stopPropagation()}>
        <HeaderArea>
          <HeaderTopRow>
            <Title>증강 현황</Title>
            <CloseButton onClick={onClose} title="닫기">
              ✕
            </CloseButton>
          </HeaderTopRow>
        </HeaderArea>

        {resolvedTeam.length > 0 && (
          <EntryContainer>
            {resolvedTeam.map((poke, idx) => {
              const isSelected = activePokemon === poke || (activePokemon?.sampleName || activePokemon?.id) === (poke.sampleName || poke.id);
              const pokeId = poke.uniqueKey;
              const count = (poke.augments || []).filter((a) => isNormalAugment(a)).length;
              return (
                <EntryCard key={poke.originalIndex ?? poke.sampleName ?? poke.id ?? idx} $isSelected={isSelected} onClick={() => {
                  setActivePokemon(poke);
                  setSelectedAugId(null);
                }} title={`${poke.name} (보유 증강 ${count}/3)`}>
                  <EntryPokemonImg
                    src={`/pokemon/img/pokemon/${pokeId}.webp`}
                    alt={poke.name}
                    onError={(e) => {
                      e.currentTarget.src = "/pokemon/img/pokemon/0000.webp";
                    }}
                  />
                  <EntryPokemonName>{poke.name}</EntryPokemonName>
                  <EntryCountBadge $hasAugment={count > 0}>{count}/3</EntryCountBadge>
                </EntryCard>
              );
            })}
          </EntryContainer>
        )}

        <CardContainer onClick={() => setSelectedAugId(null)}>
          {sortedAugments.length === 0 ? (
            <EmptyChoiceText>보유 중인 증강이 없습니다.</EmptyChoiceText>
          ) : (
            sortedAugments.map((aug, index) => {
              const isCardSelected = selectedAugId === aug.id;
              const isCurse = isCurseAugment(aug);
              const isSynergy = isSynergyAugment(aug);
              const isBuff = isBuffAugment(aug);
              const sampleKey = AUGMENT_POKEMON_PREVIEW_MAP[aug.id];
              const previewSample = sampleKey ? sampleList.getDataBySampleName(sampleKey) : null;
              const synergyData = getAugmentSynergyInfo(aug.id);
              const grantData = getAugmentGrantInfo(aug.id);
              const hasPreview = Boolean(previewSample || synergyData || grantData);
              return (
                <AugmentCard
                  key={aug.id || index}
                  $isSelected={isCardSelected}
                  $isBuff={isBuff}
                  $isCurse={isCurse}
                  $isSynergy={isSynergy}
                  onClick={(e) => handleCardClick(e, aug)}
                >
                  <IconCol>
                    <IconWrapper>
                      <AugmentIcon id={aug.id} size={38} pokemon={activePokemon} shiftUp={aug.shiftUp} imageOptions={aug.imageOptions} />
                    </IconWrapper>
                    {!isBuff && !isCurse && !isSynergy && aug.cost !== "-" && aug.cost !== undefined && <CostBadge $isLong={String(aug.cost).length >= 3}>{aug.cost ?? 1} cost</CostBadge>}
                  </IconCol>
                  <CardContent>
                    <CardTitleRow>
                      <CardTitle>{aug.shortName || aug.name}</CardTitle>
                      {isCurse ? <CurseBadge>디버프</CurseBadge> : isSynergy ? <SynergyBadge>시너지</SynergyBadge> : isBuff ? <BuffBadge>버프</BuffBadge> : null}
                    </CardTitleRow>
                    <CardDescription>{getAugmentText(aug, activePokemon, false, "", { battle, showCurrentStats: true }) || aug.desc}</CardDescription>
                  </CardContent>
                  {isCardSelected && hasPreview && (
                    <CardPreviewOverlay>
                      <PreviewInfoButton
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          if (previewSample) {
                            setPreviewInfo({ augmentId: aug.id, pokemon: previewSample });
                          } else if (synergyData) {
                            setSynergyPreviewInfo({ augmentId: aug.id, synergy: synergyData });
                          } else if (grantData) {
                            setGrantPreviewInfo({ augmentId: aug.id, grant: grantData });
                          }
                        }}
                        title={
                          previewSample
                            ? (aug.id === "eternamax" || aug.id === "blackNight"
                                ? "무한다이맥스 / 무한다이노 상세정보 보기"
                                : `${previewSample.megaData?.name || previewSample.name} 상세정보 보기`)
                            : synergyData ? `${synergyData?.title || "시너지"} 공명 상세정보 보기` : grantData ? `${grantData.modalTitle} 보기` : "상세정보 보기"
                        }
                      >
                        상세정보
                      </PreviewInfoButton>
                    </CardPreviewOverlay>
                  )}
                </AugmentCard>
              );
            })
          )}
        </CardContainer>

        <ButtonGroup>
          <CloseActionButton type="button" onClick={onClose}>
            닫기
          </CloseActionButton>
        </ButtonGroup>
      </ModalContainer>
      {previewInfo && (
        <AugmentPokemonPreviewModal
          augmentId={previewInfo.augmentId}
          pokemon={previewInfo.pokemon}
          onClose={() => setPreviewInfo(null)}
        />
      )}
      {synergyPreviewInfo && (
        <AugmentSynergyPreviewModal
          synergy={synergyPreviewInfo.synergy}
          activeAugmentId={synergyPreviewInfo.augmentId}
          activePokemon={activePokemon}
          battle={battle}
          team={resolvedTeam}
          onClose={() => setSynergyPreviewInfo(null)}
        />
      )}
      {grantPreviewInfo && (
        <AugmentGrantPreviewModal
          augmentId={grantPreviewInfo.augmentId}
          grantInfo={grantPreviewInfo.grant}
          pokemon={activePokemon}
          battle={battle}
          onClose={() => setGrantPreviewInfo(null)}
        />
      )}
    </ModalOverlay>
  );
};

export default AugmentStatusModal;

const fadeIn = keyframes`
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
`;

const ModalOverlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.65);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 10010;
  animation: ${fadeIn} 0.2s ease-out;
  padding: 16px;
  box-sizing: border-box;
  cursor: pointer;

  @media (max-width: 480px) {
    padding: 8px;
  }
`;

const ModalContainer = styled.div`
  height: 70vh;
  max-height: 70vh;
  background: rgba(15, 20, 28, 0.96);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 12px;
  padding: 18px 16px;
  width: 100%;
  max-width: 430px;
  display: flex;
  flex-direction: column;
  align-items: center;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.85);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  cursor: default;

  @media (max-width: 480px) {
    padding: 14px 10px;
    width: 96%;
  }

  &::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, #64ffda, #38bdf8, #64ffda);
  }
`;

const HeaderArea = styled.div`
  width: 100%;
  margin-bottom: 12px;
`;

const HeaderTopRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
`;

const Title = styled.h2`
  margin: 0;
  font-size: 1.15rem;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: 0.5px;
`;

const CloseButton = styled.div`
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.95rem;
  color: #94a3b8;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.1);
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;

  &:hover {
    color: #fff;
    background: rgba(239, 68, 68, 0.6);
    border-color: rgba(239, 68, 68, 0.8);
  }
`;

const EntryContainer = styled.div`
  display: flex;
  gap: 8px;
  width: 100%;
  margin-bottom: 12px;
  box-sizing: border-box;

  @media (max-width: 480px) {
    gap: 6px;
    margin-bottom: 10px;
  }
`;

const EntryCard = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 8px 4px;
  background: ${(props) => (props.$isSelected ? "rgba(20, 48, 64, 0.95)" : "rgba(255, 255, 255, 0.05)")};
  border: ${(props) => (props.$isSelected ? "2px solid #64ffda" : "1px solid rgba(255, 255, 255, 0.12)")};
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: ${(props) => (props.$isSelected ? "0 0 10px rgba(100, 255, 218, 0.35)" : "none")};
  user-select: none;
  min-width: 0;

  @media (max-width: 480px) {
    padding: 6px 2px;
  }

  &:hover {
    ${(props) =>
      !props.$isSelected &&
      `
      background: rgba(255, 255, 255, 0.09);
      border-color: rgba(100, 255, 218, 0.4);
    `}
  }
`;

const EntryPokemonImg = styled.img`
  width: 28px;
  height: 28px;
  object-fit: contain;
  flex-shrink: 0;
`;

const EntryPokemonName = styled.span`
  font-size: 0.8rem;
  font-weight: 700;
  color: #ffffff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
  text-align: center;

  @media (max-width: 480px) {
    font-size: 0.74rem;
  }
`;

const EntryCountBadge = styled.span`
  font-size: 0.65rem;
  font-weight: 700;
  color: ${(props) => (props.$hasAugment ? "#64ffda" : "#94a3b8")};
  background: ${(props) => (props.$hasAugment ? "rgba(100, 255, 218, 0.12)" : "rgba(255, 255, 255, 0.06)")};
  padding: 1px 5px;
  border-radius: 4px;
  line-height: 1.2;
`;

const CardContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  box-sizing: border-box;
  padding-right: 4px;

  &::-webkit-scrollbar {
    width: 6px;
  }
  &::-webkit-scrollbar-thumb {
    background: rgba(100, 255, 218, 0.3);
    border-radius: 4px;
  }
`;

const EmptyChoiceText = styled.div`
  font-size: 0.85rem;
  color: #94a3b8;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  width: 100%;
  padding: 32px 0;
`;

const IconCol = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 50px;
  min-width: 50px;
  margin-right: 14px;
  flex-shrink: 0;
  gap: 4px;

  @media (max-width: 480px) {
    width: 44px;
    min-width: 44px;
    margin-right: 10px;
  }
`;

const IconWrapper = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
`;

const AugmentCard = styled.div`
  position: relative;
  width: 100%;
  cursor: pointer;
  user-select: none;
  background: ${(props) =>
    props.$isCurse
      ? props.$isSelected
        ? "rgba(68, 22, 26, 0.96)"
        : "rgba(239, 68, 68, 0.12)"
      : props.$isSynergy
        ? props.$isSelected
          ? "rgba(50, 42, 16, 0.98)"
          : "rgba(255, 215, 0, 0.12)"
        : props.$isBuff
          ? props.$isSelected
            ? "rgba(14, 45, 68, 0.98)"
            : "rgba(56, 189, 248, 0.12)"
          : props.$isSelected
            ? "rgba(22, 45, 64, 0.98)"
            : "rgba(0, 0, 0, 0.45)"};
  border: ${(props) =>
    props.$isCurse
      ? props.$isSelected
        ? "1.5px solid #ef4444"
        : "1px solid rgba(239, 68, 68, 0.45)"
      : props.$isSynergy
        ? props.$isSelected
          ? "1.5px solid #ffd700"
          : "1px solid rgba(255, 215, 0, 0.4)"
        : props.$isBuff
          ? props.$isSelected
            ? "1.5px solid #38bdf8"
            : "1px solid rgba(56, 189, 248, 0.45)"
          : props.$isSelected
            ? "1.5px solid #64ffda"
            : "1px solid rgba(255, 255, 255, 0.1)"};
  border-left: 4px solid ${(props) =>
    props.$isCurse
      ? "#ef4444"
      : props.$isSynergy
        ? "#ffd700"
        : props.$isBuff
          ? "#38bdf8"
          : props.$isSelected
            ? "#38bdf8"
            : "#64ffda"};
  border-radius: 8px;
  padding: 12px 14px;
  display: flex;
  flex-direction: row;
  align-items: center;
  box-sizing: border-box;
  transition: all 0.2s ease;
  box-shadow: ${(props) =>
    props.$isSelected
      ? props.$isCurse
        ? "0 0 14px rgba(239, 68, 68, 0.45), inset 0 0 8px rgba(239, 68, 68, 0.15)"
        : props.$isSynergy
          ? "0 0 14px rgba(255, 215, 0, 0.45), inset 0 0 8px rgba(255, 215, 0, 0.15)"
          : props.$isBuff
            ? "0 0 14px rgba(56, 189, 248, 0.45), inset 0 0 8px rgba(56, 189, 248, 0.15)"
            : "0 0 14px rgba(100, 255, 218, 0.45), inset 0 0 8px rgba(100, 255, 218, 0.15)"
      : "none"};

  @media (max-width: 480px) {
    padding: 10px 10px;
  }

  &:hover {
    transform: translateY(-2px);
    border-color: ${(props) =>
      props.$isSelected
        ? props.$isCurse
          ? "#ef4444"
          : props.$isSynergy
            ? "#ffd700"
            : props.$isBuff
              ? "#38bdf8"
              : "#64ffda"
        : props.$isCurse
          ? "rgba(239, 68, 68, 0.7)"
          : props.$isSynergy
            ? "rgba(255, 215, 0, 0.7)"
            : props.$isBuff
              ? "rgba(56, 189, 248, 0.7)"
              : "rgba(100, 255, 218, 0.5)"};
    border-left: 4px solid ${(props) => (props.$isCurse ? "#ef4444" : props.$isSynergy ? "#ffd700" : props.$isBuff ? "#38bdf8" : "#64ffda")};
    background: ${(props) =>
      props.$isSelected
        ? props.$isCurse
          ? "rgba(68, 22, 26, 0.98)"
          : props.$isSynergy
            ? "rgba(50, 42, 16, 0.98)"
            : props.$isBuff
              ? "rgba(14, 45, 68, 0.98)"
              : "rgba(22, 45, 64, 0.98)"
        : props.$isCurse
          ? "rgba(68, 22, 26, 0.25)"
          : props.$isSynergy
            ? "rgba(50, 42, 16, 0.25)"
            : props.$isBuff
              ? "rgba(14, 45, 68, 0.25)"
              : "rgba(20, 30, 44, 0.75)"};
    box-shadow: 0 4px 12px
      ${(props) =>
        props.$isCurse
          ? "rgba(239, 68, 68, 0.25)"
          : props.$isSynergy
            ? "rgba(255, 215, 0, 0.25)"
            : props.$isBuff
              ? "rgba(56, 189, 248, 0.25)"
              : "rgba(0, 0, 0, 0.4)"};

    ${IconWrapper} {
      transform: scale(1.05);
      filter: drop-shadow(
        0 0 6px
          ${(props) =>
            props.$isCurse
              ? "rgba(239, 68, 68, 0.5)"
              : props.$isSynergy
                ? "rgba(255, 215, 0, 0.5)"
                : props.$isBuff
                  ? "rgba(56, 189, 248, 0.5)"
                  : "rgba(100, 255, 218, 0.4)"}
      );
    }
  }

  &:active {
    transform: scale(0.98);
  }
`;

const CardTitleRow = styled.div`
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
`;

const BuffBadge = styled.span`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1px 6px;
  font-size: 0.72rem;
  font-weight: 700;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.18);
  border: 1px solid rgba(56, 189, 248, 0.5);
  border-radius: 4px;
  letter-spacing: 0.5px;
`;

const SynergyBadge = styled.span`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1px 6px;
  font-size: 0.72rem;
  font-weight: 700;
  color: #ffd700;
  background: rgba(255, 215, 0, 0.18);
  border: 1px solid rgba(255, 215, 0, 0.5);
  border-radius: 4px;
  letter-spacing: 0.5px;
`;

const CurseBadge = styled.span`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1px 6px;
  font-size: 0.72rem;
  font-weight: 700;
  color: #f87171;
  background: rgba(239, 68, 68, 0.18);
  border: 1px solid rgba(239, 68, 68, 0.5);
  border-radius: 4px;
  letter-spacing: 0.5px;
`;

const CardContent = styled.div`
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: left;
  flex: 1;
  min-width: 0;
`;

const CardTitle = styled.h3`
  margin: 0 0 4px 0;
  font-size: 0.95rem;
  font-weight: 700;
  color: #ffffff;
  word-break: keep-all;
  line-height: 1.3;

  @media (max-width: 480px) {
    font-size: 0.86rem;
    letter-spacing: -0.3px;
    margin-bottom: 2px;
  }
`;

const CostBadge = styled.span`
  min-width: 48px;
  width: auto;
  padding: 0 5px;
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: ${(props) => (props.$isLong ? "0.61rem" : "0.68rem")};
  letter-spacing: ${(props) => (props.$isLong ? "-0.4px" : "normal")};
  font-weight: 600;
  border-radius: 4px;
  background: rgba(100, 255, 218, 0.08);
  color: #64ffda;
  border: 1px solid rgba(100, 255, 218, 0.25);
  white-space: nowrap;
  text-align: center;
  box-sizing: border-box;

  @media (max-width: 480px) {
    width: 44px;
    min-width: 44px;
    max-width: 44px;
    height: 16px;
    font-size: ${(props) => (props.$isLong ? "0.58rem" : "0.64rem")};
  }
`;

const CardDescription = styled.p`
  margin: 0;
  font-size: 0.8rem;
  color: #cbd5e1;
  line-height: 1.4;
  word-break: keep-all;
  white-space: pre-wrap;

  @media (max-width: 480px) {
    font-size: 0.76rem;
    line-height: 1.35;
  }
`;

const ButtonGroup = styled.div`
  display: flex;
  width: 100%;
  margin-top: 14px;
  box-sizing: border-box;
`;

const CloseActionButton = styled.button`
  width: 100%;
  padding: 10px 0;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 700;
  font-family: inherit;
  transition: all 0.2s ease;
  user-select: none;
  background: linear-gradient(135deg, #0d9488, #0284c7);
  border: 1px solid #64ffda;
  color: #ffffff;
  cursor: pointer;
  box-shadow: 0 0 12px rgba(100, 255, 218, 0.35);

  &:hover {
    background: linear-gradient(135deg, #14b8a6, #0284c7);
    box-shadow: 0 0 16px rgba(100, 255, 218, 0.55);
    transform: translateY(-1px);
  }

  &:active {
    transform: translateY(1px);
  }
`;


const CardPreviewOverlay = styled.div`
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  pointer-events: none;
`;

const PreviewInfoButton = styled.button`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  min-width: 96px;
  padding: 14px 26px;
  background: rgba(15, 23, 42, 0.96);
  border: 1.5px solid #64ffda;
  border-radius: 8px;
  color: #64ffda;
  font-size: 0.95rem;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
  pointer-events: auto;
  transition: all 0.2s ease;
  user-select: none;
  white-space: nowrap;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.85), 0 0 14px rgba(100, 255, 218, 0.4);
  animation: ${fadeIn} 0.15s ease-out;

  &:hover {
    background: #64ffda;
    color: #0f172a;
    box-shadow: 0 4px 22px rgba(0, 0, 0, 0.9), 0 0 18px rgba(100, 255, 218, 0.7);
    transform: scale(1.04);
  }

  &:active {
    transform: scale(0.97);
  }

  @media (max-width: 480px) {
    min-height: 44px;
    min-width: 84px;
    font-size: 0.86rem;
    padding: 10px 18px;
  }
`;
