export const getItemDesc = (itemName, pokemon = null) => {
  if (!itemName) return "";
  if (itemName === "마음의물방울" && pokemon?.hasAugment?.("soulDew")) {
    return "라티아스나 라티오스가 지니게 하면 특공과 특방이 1.5배 상승한다.";
  }
  return itemText[itemName] || itemName;
};
